    mc0, mc1 = min(c for r,c in maroon), max(c for r,c in maroon)
    mcr = (mr0 + mr1) / 2
    mcc = (mc0 + mc1) / 2
    ocr = sum(r for r,c in orange) / len(orange)
    occ = sum(c for r,c in orange) / len(orange)
    for r,c in orange:
        out[r][c] = 6
    for r,c in maroon:
        out[r][c] = 7
    vertical_motion = abs(ocr-mcr) > abs(occ-mcc)
    lo, hi = sorted((ocr,mcr) if vertical_motion else (occ,mcc))

    # Fill each empty interval between consecutive black marks that lies on
    # the route from the new orange square to its former position.
    for r in range(h):
        zs = [c for c in range(w) if grid[r][c] == 0]
        for a,b in zip(zs,zs[1:]):
            if b <= a+1 or any(grid[r][c] != 6 for c in range(a+1,b)):
                continue
            pos = r if vertical_motion else (a+b)/2
            overlaps = not (b < mc0 or a > mc1)
            if lo < pos < hi and overlaps:
                for c in range(a+1,b):
                    out[r][c] = 2
    for c in range(w):
        zs = [r for r in range(h) if grid[r][c] == 0]
